static void testTransients(const File& root,Assets& assets){
    AudioBuffer<float> audio(2,48000);audio.clear();audio.setSample(0,4807,.8f);audio.setSample(1,9613,-.7f);audio.setSample(0,9650,.6f);audio.setSample(1,24003,.9f);std::vector<int> markers{99};TransientOptions options;
    expect(findWaveTransients(audio,48000,0,48000,options,markers).wasOk()&&markers==std::vector<int>({4807,9613,24003}),"transient detection finds stereo attacks and debounces adjacent peaks");
    auto first=markers;expect(findWaveTransients(audio,48000,0,48000,options,markers).wasOk()&&markers==first,"transient detection is deterministic");
    expect(findWaveTransients(audio,48000,12000,30000,options,markers).wasOk()&&markers==std::vector<int>{24003},"transient selection excludes out-of-range attacks");
    AudioBuffer<float> quiet(2,48000);quiet.clear();expect(findWaveTransients(quiet,48000,0,48000,options,markers).wasOk()&&markers.empty(),"silent detection returns no markers");quiet.setSample(0,12000,.001f);expect(findWaveTransients(quiet,48000,0,48000,options,markers).wasOk()&&markers.empty(),"noise floor excludes quiet impulses");options.thresholdDb=-70;expect(findWaveTransients(quiet,48000,0,48000,options,markers).wasOk()&&markers==std::vector<int>{12000},"lower noise floor recovers quiet attacks");options={};
    for(int ch=0;ch<2;++ch)FloatVectorOperations::fill(quiet.getWritePointer(ch),.2f,48000);expect(findWaveTransients(quiet,48000,0,48000,options,markers).wasOk()&&markers.empty(),"sustained constant audio does not create repeated markers");
    quiet.clear();quiet.setSample(0,4807,.8f);quiet.setSample(0,4900,.9f);quiet.setSample(0,24003,.7f);options.minGapMs=100;expect(findWaveTransients(quiet,48000,0,48000,options,markers).wasOk()&&markers==std::vector<int>({4807,24003}),"minimum gap suppresses closely spaced peaks");
    markers={123,456};options.ratio=1;expect(findWaveTransients(audio,48000,0,48000,options,markers).failed()&&markers==std::vector<int>({123,456}),"invalid rise ratio preserves existing markers");options={};options.thresholdDb=std::numeric_limits<double>::quiet_NaN();expect(findWaveTransients(audio,48000,0,48000,options,markers).failed()&&markers.size()==2,"non-finite detection settings are atomic");options={};expect(findWaveTransients(audio,48000,-1,48000,options,markers).failed()&&markers.size()==2,"invalid detection selection is atomic");
    AudioBuffer<float> dense(2,64000);dense.clear();for(int at=200;at<64000;at+=160)dense.setSample(0,at,.9f);options.minGapMs=10;options.ratio=1.25;expect(findWaveTransients(dense,8000,0,64000,options,markers).failed()&&markers==std::vector<int>({123,456}),"excess transient density rejects before replacing markers");
    auto song=emptyProject();song.bpm=120;auto path=root.getChildFile("marked-slices.wav");Project output=demoProject();auto before=JSON::toString(projectToJson(output));
    expect(sliceWaveFramesToPlaylist(song,7,path.getFullPathName(),48000,48000,{100,4807,9613,24003,47900},2,output).wasOk()&&output.clips.size()==4,"irregular marker boundaries create audio clips");bool exact=true;std::vector<int> bounds={100,4807,9613,24003,47900};for(int i=0;i<4;++i){auto& clip=output.clips[(size_t)i];exact&=std::llround(clip.sourceOffset*48000)==bounds[(size_t)i]&&std::llround(clip.length*24000)==bounds[(size_t)i+1]-bounds[(size_t)i];}expect(exact,"irregular slices preserve every source frame boundary");
    output=demoProject();expect(sliceWaveFramesToPlaylist(song,7,path.getFullPathName(),48000,48000,{0,12000,12000,48000},0,output).failed()&&JSON::toString(projectToJson(output))==before,"duplicate boundaries reject the entire slice batch");expect(sliceWaveFramesToPlaylist(song,7,path.getFullPathName(),48000,48000,{0,24000,12000,48000},0,output).failed(),"unsorted slice boundaries rejected");expect(sliceWaveFramesToPlaylist(song,7,path.getFullPathName(),48000,48000,{-1,48000},0,output).failed(),"negative marker frame rejected");expect(sliceWaveFramesToPlaylist(song,7,path.getFullPathName(),48000,48000,{0,48001},0,output).failed(),"out-of-file marker rejected");expect(sliceWaveFramesToPlaylist(song,7,path.getFullPathName(),48000,48000,{0},0,output).failed(),"slice batch needs two endpoint boundaries");
    std::vector<int> capacity;for(int i=0;i<=maxClips;++i)capacity.push_back(i*80);expect(sliceWaveFramesToPlaylist(song,7,path.getFullPathName(),48000,48000,capacity,0,output).wasOk()&&output.clips.size()==maxClips,"general boundary slicing retains full 512-clip capacity for grid slicing");song.clips={{7,0,0,1}};expect(sliceWaveFramesToPlaylist(song,7,path.getFullPathName(),48000,48000,capacity,0,output).failed(),"existing clips count against irregular slicing capacity");song.clips.clear();
    AudioBuffer<float> tone(2,48000);for(int i=0;i<48000;++i){tone.setSample(0,i,.3f*std::sin(i*.019));tone.setSample(1,i,.2f*std::sin(i*.031));}auto stream=path.createOutputStream();WavAudioFormat wav;std::unique_ptr<AudioFormatWriter> writer(stream?wav.createWriterFor(stream.get(),48000,2,32,{},0):nullptr);expect(writer!=nullptr,"create irregular slice render fixture");if(writer){stream.release();writer->writeFromAudioSampleBuffer(tone,0,48000);writer.reset();}
    song.loop=false;song.songMode=true;song.tracks[7].send=0;expect(sliceWaveFramesToPlaylist(song,7,path.getFullPathName(),48000,48000,{100,4807,9613,24003,47900},0,output).wasOk(),"create renderable irregular slices");auto reference=song;Clip clip;clip.track=7;clip.audioPath=path.getFullPathName();clip.sourceOffset=100/48000.;clip.length=47800/24000.;reference.clips={clip};auto sliced=render(output,assets,root,52000,127),whole=render(reference,assets,root,52000,512);float difference=0;for(int ch=0;ch<2;++ch)for(int i=0;i<52000;++i)difference=jmax(difference,std::abs(sliced.getSample(ch,i)-whole.getSample(ch,i)));expect(sliced.getMagnitude(0,0,52000)>.001f&&difference<.00001f,"irregular marked slices render continuously across callback sizes");
}
